    import quotes.reflect.*

    TypeRepr.of[T].classSymbol match
      case None => '{ Map.empty[String, () => Any] }
      case Some(sym: Symbol) =>
        try
          val comp = sym.companionClass
          val mod  = Ref(sym.companionModule)
