          '{ $defaultsThunksExpr.toMap }
        catch // TODO drop after https://github.com/lampepfl/dotty/issues/19732 (after bump to 3.3.4)
          case cce: ClassCastException =>
            '{
              Map.empty[String, () => Any]
            }
